#!/bin/sh
set -eu

# One-time CasaRay v2 B1 reconciliation patch.
# Generated from the owner-supplied Home Assistant Developer Tools entity export
# on 2026-09-05. Safe by default: checks the patch before changing the dashboard.

ROOT="$(git rev-parse --show-toplevel)"
cd "$ROOT"

TARGET="dashboards/casaray_v2.yaml"
PATCH="$(mktemp)"
trap 'rm -f "$PATCH" "$PATCH.gz"' EXIT

cat > "$PATCH.gz.b64" <<'B64'

B64

base64 -d "$PATCH.gz.b64" > "$PATCH.gz"
gzip -dc "$PATCH.gz" > "$PATCH"
rm -f "$PATCH.gz.b64"

if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found" >&2
  exit 1
fi

if ! git diff --quiet -- "$TARGET"; then
  echo "ERROR: $TARGET already has uncommitted changes. Refusing to overwrite." >&2
  git status --short -- "$TARGET"
  exit 1
fi

echo "Checking B1 reconciliation patch..."
git apply --check "$PATCH"

echo "Applying B1 reconciliation to $TARGET..."
git apply "$PATCH"

git diff --check -- "$TARGET"

echo "B1 reconciliation applied successfully."
echo "Next: run bash scripts/ha_validate.sh, then inspect git diff before committing."
